function rawTags(source) {
  assert.equal(source.toString('ascii',0,3),'CWS');const body=inflateSync(source.subarray(8));
  assert.equal(body.length+8,source.readUInt32LE(4));const start=Math.ceil((5+4*(body[0]>>3))/8)+4,records=[];
  function scan(begin,end,domain){let p=begin,frame=1,ended=false;while(p<end){const offset=p;assert.ok(p+2<=end);const h=body.readUInt16LE(p);p+=2;const code=h>>6;let n=h&63;if(n===63){assert.ok(p+4<=end);n=body.readUInt32LE(p);p+=4;}assert.ok(p+n<=end);const payload=body.subarray(p,p+n),record={code,domain,frame,offset:offset+8,payloadOffset:p+8,payload};records.push(record);if(code===39)scan(p+4,p+n,`sprite-${payload.readUInt16LE(0)}`);p+=n;if(code===1)frame++;if(code===0){ended=true;assert.equal(p,end);break;}}assert.ok(ended);}
  scan(start,body.length,'root');return records;
}
function actionPool(action) {
  assert.equal(action[0],0x88);const n=action.readUInt16LE(1),payload=action.subarray(3,3+n);assert.equal(payload.readUInt16LE(0),8);let p=2;const pool=[];
  while(p<payload.length){const end=payload.indexOf(0,p);assert.ok(end>=p);const b=payload.subarray(p,end);assert.ok(b.every(v=>v<128));pool.push(b.toString('ascii'));p=end+1;}assert.equal(pool.length,8);
  assert.deepEqual(pool.slice(0,2),['_global','KeyAttribute']);assert.deepEqual(pool.slice(3),['_root','DoHyperLinks','animation_mc','animation','stop']);
  const replaced=[...pool];replaced[2]='__LITERAL_KEY__';const count=Buffer.alloc(2);count.writeUInt16LE(8);const normalizedPool=Buffer.concat([count,...replaced.map(s=>Buffer.from(s+'\0','ascii'))]),header=Buffer.alloc(3);header[0]=0x88;header.writeUInt16LE(normalizedPool.length,1);
  return {pool,normalized:Buffer.concat([header,normalizedPool,action.subarray(3+n)])};
}
