  const scaffold=JSON.parse(bytes(AUDIT+'/source-scaffold-snapshot.json'));const manifest=JSON.parse(scaffold.files['migration.json'].text);
  manifest.status='audited';manifest.confidence='source-structural-locked-runtime-pending';manifest.classification={collection:'course',grade:'G6-G8 shared',lesson:12,section:'VB',page:9,domain:'geometry-coordinates',knowledgePoint:{en:placement.titleEnglish,es:placement.titleSpanish},titleRaw:placement.titleRaw,titleDisplay:placement.titleEnglish,status:'confirmed',evidence:[{path:'audit/source-placement.json',kind:'exact catalog source/page association'},{path:'audit/source-behavior.json',kind:'source text and AVM1 structure'}]};
