function renderReport({behavior,catalog,audio,keyterms,placement,tc,definitions}) {
  const buttonTable=behavior.buttons.map(b=>`| ${b.characterId} | ${b.literalKey} | ${b.instance.firstFrame}–${b.instance.lastFrameExclusive-1} | ${b.instance.depth} | \`${b.actionWithCondition.sha256}\` |`).join('\n');
  const textTable=catalog.textDefinitions.map(t=>{const instances=catalog.timelines.flatMap(l=>l.instances.filter(i=>i.characterId===t.characterId));return `| ${t.characterId} | ${t.runs.length} | ${instances.length} | ${instances.map(i=>`${i.firstFrame}–${i.lastFrameExclusive-1}`).join(', ')} | ${t.runs.map(r=>r.text).join('').trim().replaceAll('|','\\|')} |`;}).join('\n');
  const maskTable=behavior.masks.map(m=>`| ${m.characterId} | ${m.instanceId} | ${m.depth+1}–${m.structuralDepthRange} | ${m.firstFrame}–${m.lastFrameExclusive-1} | ${m.events.length} |`).join('\n');
  return `# P009 source audit — 2026-09-27\n\nThis receipt establishes source custody, public-tool extraction, exact AVM1 bodies and structural frame/text/mask/audio evidence for \`${ID}\`. It is a bounded source audit. All implementation, runtime, audio, review, completion and publication gates in \`audit/extraction-receipt.json\` remain false.\n\n## Source and canonical placement\n\n- Physical source: \`${SOURCE_PATH}\`; ${SOURCE_BYTES} bytes; SHA-256 \`${SOURCE_SHA}\`. The source, every ancestor and the explicit AWS root are real paths without symlinks; source link count is one. Source bytes are unchanged and \`audit/source-input.swf\` is byte identical.\n- SWF-only: catalog FLA is null and the same-path FLA is absent. No FLA was fabricated or compiled.\n- Catalog occurrence: ${placement.stableLessonKey}, page ordinal ${placement.globalOrdinal}, ${placement.sectionCode} section ordinal ${placement.sectionPageOrdinal}, \`${placement.reference}\`. English title: ${placement.titleEnglish}; Spanish navigation title: ${placement.titleSpanish}. A Spanish navigation title does not prove Spanish animation content. The individual source/page record is frozen in \`audit/source-placement.json\`; the shared catalog is unchanged.\n- CWS / SWF 6; declared decompressed length 189,365 bytes; stage 800 × 600; 12 fps; source background RGB (184,216,247), \`#b8d8f7\`. Root has 10 observed/declared frames. Main \`sprite-62\` has 394 observed/declared frames. The main nominal visual span is ${(394/12).toFixed(6)} seconds; it is not a decoded/listened audio duration.\n\n## Tool and extraction custody\n\nFFDec 26.2.1 ran directly through the hash-verified Java/JAR/classpath in \`audit/source-toolchain.json\`, with headless public CLI XML/AS/P-code/plain-text/tag-list export. XML schema 2.2 is preserved in \`audit/movie.xml\`. Ten AS files and ten P-code-with-hex files cover the two root actions and all eight button handlers; 16 plain-text exports cover every static text definition. Raw outputs, exact argument arrays, exit status zero and stderr are recorded in the extraction receipt. The unsupported \`-version\` probe exited one and remains as a dated failure witness; successful \`-help\` identified 26.2.1. No original Flash/authoring runtime was executed.\n\nThe audit generator independently rereads the physical SWF using both maintained parsers plus a bounded recursive raw-tag walk, checks FFDec P-code hex against source bytes, and reconstructs all derived files. \`node audit/build-source-audit.mjs --check\` is read-only and fails on source/tool/output drift. The original scaffold content is retained in \`audit/source-scaffold-snapshot.json\`; the scaffold keyframes, full-frame-coverage and checklist remain byte identical. The root-only scaffold coverage is pending evidence and does not cover the main 394-frame domain.\n\n## Root, ownership and source ActionScript\n\nAt root frame 1, the exact 73-byte body calls \`_level0.InternalPreloader.gotoAndPlay("jump_check")\`, then \`stop()\`; root frame 6 carries the exact two-byte \`stop()\`. Root frame 6 also places \`sprite-62\` at depth 1, name \`animation\`, ratio 5, matrix \`[1,0,0,1,8248,5666]\` in twips; shape 63 is at depth 85 with identity matrix; the peer native/graphics source inventory identifies it as an outlined title. The source-behavior JSON historical property name \`borderInstance\` retains the same structural instance and makes no geometry classification. A source static graph establishes only these definitions/placements. The legacy wrapper’s \`animation_mc\` ownership, loading order and resumed natural trace require original runtime evidence. Implement only a page-scoped typed adapter in the retained modern Lesson/My Lesson host.\n\nMain has no DoAction/DoInitAction/DoABC tag, no nested child sprite, no main terminal stop action and no Replay action. A future product terminal hold or whole-page Replay must be explicit and tested; it must not be attributed to a source handler. The manifest retains \`runtime.frameCount:10\` for root and declares a separate main frame domain of 394; no root/main total is substituted for the page count.\n\n## Eight exact release handlers\n\nEvery button has one condition: final condition-size zero, raw condition header \`00000800\` (release transition, no keyboard condition). Each body sets \`_global.KeyAttribute\` to its exact literal, calls \`_root.DoHyperLinks()\` with zero arguments, then calls \`_root.animation_mc.animation.stop()\` with zero arguments. The order is source-evidenced; host glossary UI, close/resume and audio consequences remain unresolved. Exact action body and action-with-condition hashes, constant pool, structural hit state, placement history and exports are retained in \`audit/source-behavior.json\`.\n\n| Button | Exact literal key | Structural main frames | Depth | Full condition/action SHA-256 |\n|---:|---|---|---:|---|\n${buttonTable}\n\nThe comparison source is \`${P007_PATH}\`, 113,668 bytes, SHA-256 \`${P007_SHA}\`. Both root action payloads match byte for byte. All P009 and P007 button condition headers match; each complete action body matches after replacing only constant-pool entry 2 (the literal key) with \`__LITERAL_KEY__\`. Normalized template SHA-256: \`${behavior.sourceComparison.normalizedTemplateSha256}\`. The full normalized bytes are recorded, and FFDec AS/P-code must independently agree. This comparison does not admit P009 to the existing P007 private adapter’s calibration regex, which excludes P009.\n\n## Static text and graphics boundary\n\nOne embedded font, Bauhaus Md BT, has 36 glyphs and a wide Unicode code table. All 16 DefineText definitions / 32 runs decode through that source table. There are no dynamic fields, bitmap definitions, unresolved runs or unparsed tags. The catalog canonical content hash (SHA-256 of \`JSON.stringify(collectSwfTextSourceCatalog(sourceBytes))\`) is \`${behavior.catalogContentSha256}\`. The pretty JSON file has its own distinct artifact hash. Decoding establishes characters; it does not establish runtime visibility, reading order, modern layout or mathematical grouping.\n\n| DefineText | Runs | Placement instances | Structural frame windows | Decoded source text |\n|---:|---:|---:|---|---|\n${textTable}\n\nThe minus sign is its own text definition (18), reused ten times; number definitions 17/19/20/21/22 have four placements each. Do not turn 16 definitions into 16 overlay instances. Definitions 60 (4) and 61 (2) each have three one-frame flashing instances (353/355/357 and 383/385/387). Definition 59 is the literal \`(4,2)\`, with three source runs and eight opacity-only events at main frames 284–291 (alpha multiply 0,37,73,110,146,183,219,256); its sole matrix is the initial [1,0,0,1,-219,-1059] and never changes. Preserve its comma, parentheses, coordinate order and per-instance transforms.\n\nAll ${definitions.filter(d=>d.kind==='vector-shape').length} vector definitions are source-exported through the XML and enumerated in \`asset-inventory.csv\`. This step makes no outlined-text/nontext classification, redraw or source suppression. The separate peer-owned native/graphics inventory must review every vector, graph segment, outlined-title shape 63 and button hit region before choosing suppression. Root transforms, glyph advances and complete placement histories are in the source catalog.\n\n## Four complete structural masks\n\n| Mask character | Instance | Covered depths | Structural main frames | Placement/update events |\n|---:|---|---|---|---:|\n${maskTable}\n\nMask definitions 1 and 29 recur at different depths. Their full histories are preserved in \`audit/source-behavior.json\`; inheriting transform updates is necessary. First placement and depth range do not prove visible word cutoffs, readable overlay timing or hit visibility. Retain graphics/masks until a source-native renderer and DOM overlay agree with independently reviewed source geometry. Parser risk \`mask-filter-blend-semantics-unresolved\` is not closed by this table.\n\n## Stream audio extraction, without implementation\n\nThe only audio stream head is main frame 1: raw \`0a2a2d078906\`, MP3 compression 2, mono 22,050 Hz, 16-bit playback/stream declarations, nominal 1,837 samples per frame, latency seek 1,673 samples. Main frames 2–394 carry 393 blocks. The only zero-payload block is frame 3 with header \`00000000\`; this does not prove silence. Each source block’s raw count/seek/header, offset, payload hash and concatenated declared count is recorded in \`audit/source-stream-blocks.json\`.\n\nConcatenating only the MP3 payload bytes after each four-byte stream block header yields \`audit/source-stream.mp3\`, ${audio.stream.bytes} bytes, SHA-256 \`${audio.stream.sha256}\`. Declared sample-count sum is ${audio.stream.declaredSampleCountSum}; counts take values ${audio.stream.sampleCountValues.join(', ')}. No decoder, scheduler, padding, trim, retime, synthetic silence, playback or listening step was performed. A declared count sum is not decoded duration or frame/sample synchronization.\n\nThe physical sidecar \`${SIDECAR_PATH}\` is 325,584 bytes, SHA-256 \`${SIDECAR_SHA}\`. It differs from the embedded stream and remains a lesson-SA catalog association only. It was neither substituted nor decoded. Audio language, host triggers, pause/close/resume/Replay and end/tail behavior require separate source/runtime evidence.\n\n## Exact bilingual key-term references\n\nBoth physical MI dictionary files are hash locked. Each of the eight literal keys matches one source record per file, including the slash-bearing \`Coordinate plane/Cartesian Plane\` tag and multiline Spanish entries. \`audit/source-keyterms.json\` preserves exact source tags, line ranges, attributes, EN/ES labels, definitions and hashes. Legacy entities remain unmodified and require a typed safe rich-text conversion in the product. Source dictionary presence does not prove glossary animation/audio custody or a functioning original host. Page text is source English for EN; ES must disclose source-English fallback until an independently audited Spanish page source exists.\n\n## Concrete maintained implementation route\n\n1. Use the compiler-assisted hybrid workflow with \`interactive-understood\` page scope. Reuse source bytes/extraction and maintained parsers. Do not run a linear bulk factory across a page with eight buttons.\n2. Build a P009-scoped typed glossary state machine carrying the exact literal key and current main frame. Button release requests the modern glossary and pauses content; keyboard/touch behavior, focus return, close/resume and Replay need deterministic product tests. Do not execute legacy globals or pretend the P007 adapter’s existing calibration regex allows this page.\n3. Integrate the separate native source inventory into \`LessonTextPresentation\` and the modern host. Bind all 16 definitions / 32 sourceTextIds and every visible instance; use exact source shape/instance suppression only after graphics and four mask dispositions are established. Keep the graph and mathematics visible; preserve \`(4,2)\`, signs and flashing instances.\n4. Keep this extracted stream separate from audio implementation. A later maintained decoder/transport/schedule contract must establish actual decoded length, count/seek interpretation, initial empty block, host pause/resume/Replay and terminal behavior before enabling audio.\n5. Produce page-specific native typography bindings, complete current implementation/shared file closure and fresh EN/ES responsive/zoom/keyboard/browser evidence before a bounded Current-JS admission. Source audit and template reuse alone cannot register the page.\n6. Later original-runtime, fidelity, listening, human/Owner, strict-completion, release and publication gates remain independent. No provider operation, product source edit, registry write or acceptance action occurred in this audit.\n\n## Remaining evidence\n\nSource FLA is absent. Original runtime/host traces and full-frame comparisons are absent. The 37 shape and four mask semantic dispositions are pending the separate peer inventory and implementation. A Spanish page text/audio source is not established. Glossary animation/audio dependencies are not audited. Audio decoding/schedule/listening is not established. Root-only scaffold keyframe/coverage records are retained as pending records and must be deliberately extended later to the main domain and actual interaction traces. Every downstream gate remains false.\n`;
}
function renderBrief({behavior,placement}) {return `# ${ID} Migration Brief\n\nSource audit: 2026-09-27. Status: source-audited draft; implementation and acceptance pending.\n\n## Objective and identity\n\nImplement source-backed ${placement.titleEnglish} (${placement.titleSpanish}) in the modern Lesson/My Lesson center. Canonical placement is ALG001 L12 P009, VB section page 3; immutable asset ID is \`swf-${SOURCE_SHA}\`. Catalog and exact instructional source establish geometry/coordinates scope. The Spanish navigation title does not establish Spanish page content.\n\n## Preserved source\n\nPhysical SWF: \`${SOURCE_PATH}\`; ${SOURCE_BYTES} bytes; SHA-256 \`${SOURCE_SHA}\`. \`audit/source-input.swf\` is byte identical. FLA is absent. Source archive and shared catalogs are unchanged. See \`audit/source-placement.json\`, \`audit/extraction-receipt.json\`, and \`evidence/SOURCE_AUDIT_2026-09-27.md\`.\n\n## Source behavior and route\n\nCWS SWF 6, 800 × 600, 12 fps, background \`#b8d8f7\`; root 10 frames, nested main sprite 62 has 394 frames. Root frame 1 requests InternalPreloader then stops; frame 6 stops and places main at depth 1 and outlined-title shape 63 at depth 85. Main has no ActionScript/terminal-stop/Replay handler. Eight exact release handlers set KeyAttribute, request DoHyperLinks, and stop animation_mc.animation. Their complete bodies and source/P007 template comparison are byte verified. Four masks and complete transform histories require native review.\n\nUse compiler-assisted extraction plus a maintained P009-scoped typed glossary state and source-native renderer. Classification is interactive-understood. Reusing the existing P007 private adapter requires an explicit reviewed scope extension or a page-specific implementation; its current calibration regex excludes this page. Every glossary request must carry the exact source key and current main frame. Close/resume, focus return, keyboard/touch, terminal hold and whole-page Replay remain explicit product contracts to implement and test. No legacy globals execute in the modern product.\n\n## Typography and graphics\n\nSource contains 16 static definitions, 32 decoded runs, one font, 37 vectors, eight buttons, zero dynamic fields/bitmaps/unparsed tags. Source catalog content SHA-256 is \`${behavior.catalogContentSha256}\`. The native/graphics inventory is separately owned. Bind sourceTextIds and all instances, preserve graph geometry, ten minus-sign instances, source literal \`(4,2)\`, the pair’s opacity-only updates and one-frame flashes. Do not suppress vector/text instances until source geometry and masks have a complete reviewed disposition. Page language policy is EN source text / ES disclosed source-English fallback; dictionary glossary records have source EN/ES entries.\n\n## Audio\n\n393 source stream blocks were extracted, not decoded or implemented. Raw head: mono 22,050 Hz MP3, nominal 1,837 samples/frame and latency seek 1,673. Frame 3 has a zero-payload block without proof of silence. Concatenated embedded MP3 is 162,890 bytes SHA-256 \`15e60f13aad0e2187db0b32f6bcfe65151001a1ded336abd4fb4eb59b3014f2e\`; sidecar differs (325,584 bytes SHA-256 \`${SIDECAR_SHA}\`). No audio schedule, language, listening, host pause/resume or terminal policy is accepted.\n\n## Evidence and verification\n\nFFDec 26.2.1 XML, 10 AS, 10 P-code-hex, 16 plain-text files and tag listing are hash bound. Maintained parser output, full 404 structural frame rows, 63 character asset rows, exact bilingual key crosswalk and per-block audio evidence are reproducible with \`HELP_MATH_G678_SOURCE_ROOT='${SOURCE_ROOT}' node migrations/${ID}/audit/build-source-audit.mjs --check\` from the implementation root. Check rereads real source/toolchain/current outputs and performs no writes. The preserved \`-version\` failure is retained; \`-help\` identified the successful actual tool.\n\n## Pending implementation and acceptance\n\nNo route, module, registry or audio implementation was written here. Original-runtime baseline/full-frame coverage, maintained native renderer, page-specific typography B/C, fresh real-host EN/ES responsive/zoom/focus tests, Flash fidelity, audio listening, human/Owner review, strict completion, release and publication remain pending. The untouched scaffold keyframes/full-frame-coverage are root-only pending evidence; later coverage must deliberately add the main and actual glossary traces. Runtime frameCount remains root 10. No source/acceptance substitution occurs.\n`;} 

function main() {
  assert.ok(process.argv.slice(2).length<=1);const mode=process.argv[2]??'--check';assert.ok(['--check','--dry-run','--write','--refresh-authored-docs'].includes(mode),'Usage: build-source-audit.mjs [--check|--dry-run|--write|--refresh-authored-docs]');
  const plan=derive(),mutable=new Set(['migration.json','MIGRATION_BRIEF.md','asset-inventory.csv','audio-inventory.csv']);
  for(const p of ['keyframes.csv','evidence/full-frame-coverage.json','ACCEPTANCE_CHECKLIST.md'])expectedFile(MIGRATION+'/'+p,plan.scaffold.files[p].sha256,plan.scaffold.files[p].bytes);
  if(mode==='--dry-run'){console.log(json({state:'SOURCE_AUDIT_INPUTS_VERIFIED_NOT_WRITTEN',...plan.summary}));return;}
  if(mode==='--refresh-authored-docs'){
    const replacements=new Set(['audit/extraction-receipt.json','evidence/SOURCE_AUDIT_2026-09-27.md','MIGRATION_BRIEF.md']);
    const predecessor=JSON.parse(bytes(AUDIT+'/source-authored-docs-predecessor-v1.json')),pins={'audit/build-source-audit.mjs':'a95d066e3128084c14f866a90848d5a65abbd390741c28404b51ea2b9b9cbae4','audit/extraction-receipt.json':'1f0e3c5da519e301b85f72950ade7db6ce4085e8b14fc9dc4cdd64f2e51e877d','evidence/SOURCE_AUDIT_2026-09-27.md':'9890e12eb13bf27c39c0a9e0f6e1cf8d9b91bc6390c2ae1af71381a27e24e809','MIGRATION_BRIEF.md':'0877a4bc0c0bec0e5dffaa53752305857225a3951420ebb45b997fa08bd96305'};
    assert.equal(predecessor.files.length,4);for(const f of predecessor.files){assert.equal(f.sha256,pins[f.path]);assert.equal(sha(f.text),f.sha256);assert.equal(Buffer.byteLength(f.text),f.bytes);if(replacements.has(f.path))expectedFile(MIGRATION+'/'+f.path,f.sha256,f.bytes);}
    for(const [p,b]of plan.outputs)if(!replacements.has(p))assert.deepEqual(bytes(MIGRATION+'/'+p),Buffer.isBuffer(b)?b:Buffer.from(b),`Source fact drift: ${p}`);
    for(const p of replacements){const temp=AUDIT+'/source-authored-docs-'+path.basename(p)+'.next';assert.ok(absent(temp));fs.writeFileSync(temp,plan.outputs.get(p),{flag:'wx'});fs.renameSync(temp,MIGRATION+'/'+p);}
  }
  if(mode==='--write'){
    for(const [p]of plan.outputs){const target=MIGRATION+'/'+p;if(mutable.has(p))expectedFile(target,plan.scaffold.files[p].sha256,plan.scaffold.files[p].bytes);else assert.ok(absent(target),`Refusing existing output: ${p}`);physical(path.dirname(target));}
    for(const [p,b]of plan.outputs)if(!mutable.has(p))fs.writeFileSync(MIGRATION+'/'+p,b,{flag:'wx'});
    for(const [p,b]of plan.outputs)if(mutable.has(p)){expectedFile(MIGRATION+'/'+p,plan.scaffold.files[p].sha256,plan.scaffold.files[p].bytes);const temp=AUDIT+'/source-'+p.replaceAll('.','-')+'-initial.next';fs.writeFileSync(temp,b,{flag:'wx'});fs.renameSync(temp,MIGRATION+'/'+p);}
  }
  for(const [p,b]of plan.outputs)assert.deepEqual(bytes(MIGRATION+'/'+p),Buffer.isBuffer(b)?b:Buffer.from(b),`Stale derived audit: ${p}`);
  expectedFile(SOURCE_PATH,SOURCE_SHA,SOURCE_BYTES);console.log(json({state:mode==='--check'?'SOURCE_AUDIT_VERIFIED_READ_ONLY':'SOURCE_AUDIT_CREATED_AND_VERIFIED',...plan.summary}));
}
if(path.resolve(process.argv[1]??'')===SCRIPT)main();
